/** Re-registers a previously enabled stream (e.g. after restart) keeping its ARN. */
public StreamDescription restoreStream(String tableName, String streamArn, String viewType,
                                       Instant creationTime, String region) {
    String key = streamKey(region, tableName);
    StreamDescription existing = streams.get(key);
    if (existing != null) {
        return existing;
    }
    int idx = streamArn.lastIndexOf("/stream/");
    String label = idx >= 0 ? streamArn.substring(idx + 8) : STREAM_LABEL_FORMAT.format(creationTime);
    StreamDescription sd = new StreamDescription();
    sd.setStreamArn(streamArn);
    sd.setStreamLabel(label);
    sd.setStreamStatus("ENABLED");
    sd.setStreamViewType(viewType);
    sd.setTableName(tableName);
    sd.setCreationDateTime(creationTime);
    sd.setStartingSequenceNumber(String.format("%021d", 1));
    streams.put(key, sd);
    records.putIfAbsent(streamArn, new ConcurrentLinkedDeque<>());
    return sd;
}

public void disableStream(String tableName, String region) {

    loadPersistedItems();
    restoreStreams();
}

private void restoreStreams() {
    if (streamService == null || tableStore == null) return;
    for (String key : tableStore.keys()) {
        tableStore.get(key).ifPresent(t -> {
            if (t.isStreamEnabled() && t.getStreamArn() != null) {
                int sep = key.indexOf("::");
                String region = sep >= 0 ? key.substring(0, sep) : "us-east-1";
                streamService.restoreStream(t.getTableName(), t.getStreamArn(),
                        t.getStreamViewType(), t.getCreationDateTime(), region);
            }
        });
    }
}

